INSERT INTO categories (id, slug, name, name_bn, description, sort_order, seo_title, seo_description) VALUES
(1, 'cat-dry-food', 'Cat Dry Food', 'বিড়ালের ড্রাই ফুড', 'Complete dry food for kittens, adult and senior cats — indoor, urinary care, skin & coat, grain free and more. Pick by your cat''s age and need.', 1, 'Cat Dry Food Price in Bangladesh — Kaniva Cat Food', 'Buy Kaniva dry cat food in Bangladesh: kitten, adult, senior, indoor, urinary and grain free formulas. Cash on delivery and fast home delivery.'),
(2, 'cat-wet-food', 'Cat Wet Food', 'বিড়ালের ওয়েট ফুড', 'Tasty pouches in jelly, gravy and mousse — high moisture meals your cat will love. Serve alone or mix with dry food.', 2, 'Cat Wet Food & Pouch Price in BD — Kaniva & Kandy', 'Kaniva and Kandy wet cat food pouches in jelly, gravy and mousse. Kitten and adult recipes with home delivery across Bangladesh.'),
(3, 'cat-treats', 'Cat Treats', 'ক্যাট ট্রিট', 'Creamy lickable treats for rewards, training, bonding and hiding medicine.', 3, 'Cat Creamy Treats Price in BD — Kaniva Lickable Treats', 'Kaniva creamy lickable cat treats in tuna, chicken, lamb and seafood flavours. Order online in Bangladesh.'),
(4, 'cat-litter', 'Cat Litter', 'ক্যাট লিটার', 'Plant-based tofu cat litter that clumps fast, controls odour and is low in dust.', 4, 'Tofu Cat Litter Price in BD — Kasty Pop 6L', 'Kasty Pop tofu cat litter 6L in six scents. Fast clumping, odour control and low dust. Delivered across Bangladesh.'),
(5, 'pet-wipes', 'Pet Wipes', 'পেট ওয়াইপস', 'Soft pet wipes for quick cleaning of paws, face, ears and coat between baths.', 5, 'Pet Wipes Price in BD — Kanimal 100 Sheets', 'Kanimal pet wipes, 100 soft sheets in six scents for cats and dogs. Order online in Bangladesh.'),
(6, 'pet-accessories', 'Accessories', 'অ্যাক্সেসরিজ', 'Everyday essentials like feeding bowls for cats and dogs.', 6, 'Pet Accessories in Bangladesh — Kaniva', 'Kaniva pet accessories including feeding bowls. Order online with home delivery in Bangladesh.'),
(7, 'dog-food', 'Dog Food', 'কুকুরের খাবার', 'Complete dry dog food with tuna and rice in salmon, lamb and chicken recipes.', 7, 'Dog Food Price in Bangladesh — Kaniva Dry Dog Food', 'Kaniva dry dog food with tuna and rice. Salmon, lamb and chicken recipes with home delivery across Bangladesh.');
INSERT INTO products (id, slug, name, short_description, description, feeding_guide, quick_info, features, images, tags, brand, sku, category_id, life_stage, food_type, flavor, is_popular, is_active, seo_title, seo_description, seo_keywords, created_at) VALUES
(1, 'kaniva-fusion-salmon-sweet-potato-cat-food', 'Kaniva Fusion Dry Cat Food – Salmon & Sweet Potato (Skin & Coat Omega Booster)', 'Kaniva Fusion Dry Cat Food – Salmon & Sweet Potato (Skin & Coat Omega Booster) is a complete dry food for adult cats. Crunchy kibble with quality animal protein, made for everyday feeding.', 'Kaniva Fusion Dry Cat Food – Salmon & Sweet Potato (Skin & Coat Omega Booster) is a complete dry food for adult cats. Crunchy kibble with quality animal protein, made for everyday feeding.
